+// Structural, not `import type`: the ajv copy tsc resolves types from need not be the one nodeRequire loads.
+interface SchemaError {
+  instancePath?: string;
+  dataPath?: string;
+  message?: string;
+}
+interface CompiledSchema {
+  (input: unknown): boolean;
+  errors?: SchemaError[] | null;
+}
+interface AjvLike {
+  new (options?: Record<string, unknown>): {compile: (schema: ToolDefinition['inputSchema']) => CompiledSchema};
