+function describeSchemaErrors(errors: SchemaError[]): string {
+  const pathOf = (error: SchemaError): string => error.instancePath ?? error.dataPath ?? 'input';
+  return errors.map(error => `${pathOf(error)} ${error.message ?? 'failed validation'}`).join('; ');
 }

